<?php $e = static fn (mixed $value): string => App\Core\View::e($value); $roles = ['referee' => 'Árbitro', 'assistant' => 'Assistente', 'fourth_official' => 'Quarto oficial', 'scorekeeper' => 'Mesário', 'coordinator' => 'Coordenador']; ?>
<section class="page-stack"><div class="section-heading"><div><p class="eyebrow">Operação esportiva</p><h1>Árbitros e oficiais</h1><p class="muted">Cadastre a equipe de arbitragem e publique a relação no portal.</p></div><a class="button" href="<?= $e(App\Core\Config::url('/admin/arbitros/novo' . ($championship ? '?championship_id=' . $championship['id'] : ''))) ?>">Novo cadastro</a></div><?php if (!empty($message)): ?><p class="success"><?= $e($message) ?></p><?php endif; ?><form class="filter-bar" method="get"><label>Campeonato <select name="championship_id"><option value="">Selecione</option><?php foreach ($championships as $item): ?><option value="<?= $item['id'] ?>" <?= $championship && (int) $championship['id'] === (int) $item['id'] ? 'selected' : '' ?>><?= $e($item['name']) ?></option><?php endforeach; ?></select></label><button type="submit">Filtrar</button></form><?php if ($championship): ?><div class="table-wrap"><table><thead><tr><th>Nome</th><th>Função</th><th>Status</th><th></th></tr></thead><tbody><?php foreach ($items as $item): ?><tr><td><strong><?= $e($item['public_name'] ?: $item['full_name']) ?></strong></td><td><?= $e($roles[$item['role']] ?? $item['role']) ?></td><td><?= $e($item['status']) ?></td><td><a href="<?= $e(App\Core\Config::url('/admin/arbitros/' . $item['id'] . '/editar')) ?>">Editar</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
